pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    let exponent = attempt.saturating_sub(1);
    let multiplier = if exponent < 64 {
        1u64 << exponent
    } else {
        u64::MAX
    };
    config
        .base_delay_ms
        .saturating_mul(multiplier)
        .min(config.max_delay_ms)
}

